private static class KeySizeConstraint implements Constraint {
    private final String operator;
    private final int size;

    public KeySizeConstraint(String operator, int size) {
        this.operator = operator;
        this.size = size;
    }

    public boolean permits(Key key) {
        int keySize = getKeySizeInBits(key);
        switch (operator) {
            case "<=":
                return keySize <= size;
            case "<":
                return keySize < size;
            case "==":
                return keySize == size;
            case "!=":
                return keySize != size;
            case ">":
                return keySize > size;
            case ">=":
                return keySize >= size;
            default:
                return false;
        }
    }

    private int getKeySizeInBits(Key key) {
        try {
            return ((java.security.KeyPair) key).getPublic().getEncoded().length * 8;
        } catch (Exception e) {
            return 0;
        }
    }

    public boolean permits(X509Certificate cert) {
        return permits((Key) cert.getPublicKey());
    }
}

